"""Payroll summary for a pay period. Usage: payroll.py INPUT_DIR OUTPUT_FILE"""
import csv
import gzip
import io
import json
import math
import os
import sys
from datetime import date, datetime, timedelta, timezone
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b.decode("utf-8-sig")


def lines_of(text):
    for ln in text.split("\n"):
        ln = ln.rstrip("\r")
        if ln.strip() == "":
            continue
        yield ln


def read_csv_rows(path):
    text = read_text(path)
    return list(csv.DictReader(io.StringIO(text)))


def to_epoch(dt):
    return int(dt.timestamp()) if dt.tzinfo else None


def local_to_instant(zone, naive, dst=None, first=True):
    """Instant (epoch seconds) of a local wall-clock time.

    For repeated local times: dst True/False picks the occurrence by DST flag;
    dst None picks the first occurrence."""
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() == b.utcoffset():
        return int(a.timestamp())
    if dst is None:
        return int(a.timestamp())
    for c in (a, b):
        if bool(c.dst()) == dst:
            return int(c.timestamp())
    return int(a.timestamp())


def std_offset_seconds(zone):
    offs = []
    for m in (1, 7):
        d = datetime(2026, m, 1, tzinfo=zone)
        offs.append(int(d.utcoffset().total_seconds()))
    return min(offs)


def parse_dir(s):
    s = str(s).strip().upper()
    if s in ("IN", "I", "CLOCK_IN", "K"):
        return "IN"
    if s in ("OUT", "O", "CLOCK_OUT", "G"):
        return "OUT"
    return None


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


# ---------------------------------------------------------------- parsers
# Each parser yields (punch_id, employee, direction, epoch_seconds)
def parse_abbr_csv(path, zone):
    text = read_text(path)
    known = {"badge", "punch", "date", "time", "zone", "terminal", "record"}
    header = None
    for row in csv.reader(io.StringIO(text)):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if {c.lower() for c in cells} >= {"badge", "punch", "date", "time"} and \
                all(c.lower() in known for c in cells):
            header = [c.lower() for c in cells]
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = parse_dir(r.get("punch"))
        if d is None:
            continue
        mo, da, yr = r["date"].split("/")
        t = r["time"].strip().upper()
        ampm = None
        if t.endswith("AM") or t.endswith("PM"):
            ampm = t[-2:]
            t = t[:-2].strip()
        parts = [int(x) for x in t.split(":")]
        while len(parts) < 3:
            parts.append(0)
        h, mi, se = parts
        if ampm == "AM":
            h = 0 if h == 12 else h
        elif ampm == "PM":
            h = 12 if h == 12 else h + 12
        naive = datetime(int(yr), int(mo), int(da), h, mi, se)
        zn = r.get("zone", "").strip().upper()
        dst = None
        if zn.endswith("DT"):
            dst = True
        elif zn.endswith("ST"):
            dst = False
        yield r["record"], r["badge"], d, local_to_instant(zone, naive, dst)


def parse_epoch_jsonl(path, zone):
    schema = 1
    for ln in lines_of(read_text(path)):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and len(o) == 1:
            schema = o["schema"]
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2 or ("punch_id" in o and "epoch_ms" in o):
            if "punch_id" not in o:
                continue
            pid, emp, d = o["punch_id"], o["employee"], parse_dir(o["direction"])
            ts = math.floor(float(o["epoch_ms"]) / 1000)
        else:
            if "id" not in o:
                continue
            pid, emp, d = o["id"], o["emp"], parse_dir(o["dir"])
            if "ts_ms" in o:
                ts = math.floor(float(o["ts_ms"]) / 1000)
            elif "ts" in o:
                ts = math.floor(float(o["ts"]))
            else:
                continue
        if d is None:
            continue
        yield str(pid), str(emp).strip(), d, ts


def parse_offset_csv(path, zone):
    text = read_text(path)
    rd = csv.DictReader(io.StringIO(text), delimiter=";", quotechar='"')
    for r in rd:
        if not r or not r.get("punch_id"):
            continue
        d = parse_dir(r["event"])
        if d is None:
            continue
        dt = parse_iso(r["timestamp"])
        yield r["punch_id"].strip(), r["employee"].strip(), d, int(dt.timestamp())


def parse_legacy_fixed(path, zone):
    std = std_offset_seconds(zone)
    off = std
    for ln in lines_of(read_text(path)):
        t = ln[0]
        if t == "H":
            off = std
            tail = ln[13:18].strip()
            if tail:
                sign = -1 if tail[0] == "-" else 1
                hh, mm = int(tail[1:3]), int(tail[3:5])
                off = sign * (hh * 3600 + mm * 60)
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = parse_dir(ln[15])
            ts = ln[16:30]
            if d is None:
                continue
            naive = datetime(int(ts[0:4]), int(ts[4:6]), int(ts[6:8]),
                             int(ts[8:10]), int(ts[10:12]), int(ts[12:14]))
            epoch = int(naive.replace(tzinfo=UTC).timestamp()) - off
            yield pid, "E" + badge, d, epoch


def parse_de_tsv(path, zone):
    text = read_text(path)
    header = None
    for ln in lines_of(text):
        cells = [c.strip() for c in ln.split("\t")]
        if "Ausweis" in cells and "Buchung" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = parse_dir(r["Buchung"])
        if d is None:
            continue
        dd, mo, yy = r["Datum"].split(".")
        parts = [int(x) for x in r["Uhrzeit"].split(":")]
        while len(parts) < 3:
            parts.append(0)
        naive = datetime(int(yy), int(mo), int(dd), *parts)
        z = r.get("Zeitzone", "").strip().upper()
        dst = True if z == "MESZ" else (False if z == "MEZ" else None)
        yield r["Nr"], r["Ausweis"], d, local_to_instant(zone, naive, dst)


def parse_local_csv(path, zone):
    for r in read_csv_rows(path):
        if not r.get("punch_ref"):
            continue
        d = parse_dir(r["direction"])
        if d is None:
            continue
        naive = datetime.strptime(r["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        yield r["punch_ref"].strip(), r["employee_id"].strip(), d, local_to_instant(zone, naive, None)


def parse_local_jsonl(path, zone):
    for ln in lines_of(read_text(path)):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        d = parse_dir(p.get("type"))
        if d is None:
            continue
        naive = datetime.strptime(p["at"].strip(), "%Y-%m-%d %H:%M:%S")
        yield str(p["id"]), str(p["badge"]).strip(), d, local_to_instant(zone, naive, None)


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy_fixed,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------- main logic
def round_instant(ts, zone):
    off = int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
    local = ts + off
    r = local % 360
    delta = (360 - r) if r >= 180 else -r
    return ts + delta


def local_date(ts, zone):
    return datetime.fromtimestamp(ts, UTC).astimezone(zone).date()


def night_minutes(tin, tout, zone):
    if tout <= tin:
        return 0
    d0 = local_date(tin, zone) - timedelta(days=1)
    d1 = local_date(tout, zone)
    total = 0
    d = d0
    while d <= d1:
        s = local_to_instant(zone, datetime(d.year, d.month, d.day, 22))
        n = d + timedelta(days=1)
        e = local_to_instant(zone, datetime(n.year, n.month, n.day, 6))
        lo, hi = max(s, tin), min(e, tout)
        if hi > lo:
            total += hi - lo
        d += timedelta(days=1)
    return total // 60


def round_half_up_cents(fr):
    return math.floor(fr * 100 + Fraction(1, 2))


def main(inp, outp):
    period = json.load(open(os.path.join(inp, "period.json")))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso(period["corrections_cutoff"])
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=UTC)

    sites = {}
    for r in read_csv_rows(os.path.join(inp, "sites.csv")):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = []
    home = {}
    for r in read_csv_rows(os.path.join(inp, "employees.csv")):
        eid = r["employee_id"].strip()
        employees.append(eid)
        home[eid] = r["home_site"].strip()

    rates = {}
    for r in read_csv_rows(os.path.join(inp, "rates.csv")):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Fraction(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect punches: (site, id) -> [employee, dir, ts]
    punches = {}
    ever = set()
    for site in sorted(sites):
        zone, fmt = sites[site]
        base = os.path.join(inp, "exports", site)
        if not os.path.isdir(base):
            continue
        files = []
        for root, _, names in os.walk(base):
            for n in names:
                files.append(os.path.join(root, n))
        for path in sorted(files):
            for pid, emp, d, ts in PARSERS[fmt](path, zone):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp, d, ts]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, "corrections")
    if os.path.isdir(cdir):
        for root, _, names in os.walk(cdir):
            for n in sorted(names):
                try:
                    rows = read_csv_rows(os.path.join(root, n))
                except Exception:
                    continue
                for r in rows:
                    if not r.get("correction_id"):
                        continue
                    r = {k: (v or "").strip() for k, v in r.items() if k}
                    try:
                        r["_at"] = parse_iso(r["issued_at"])
                        if r["_at"].tzinfo is None:
                            r["_at"] = r["_at"].replace(tzinfo=UTC)
                    except Exception:
                        continue
                    corr.append(r)
    corr = [c for c in corr if c["_at"] <= cutoff]
    corr.sort(key=lambda c: (c["_at"], c["correction_id"]))
    applied = 0
    for c in corr:
        key = (c["site"], c["punch_id"])
        act = c["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                try:
                    punches[key][2] = int(parse_iso(c["time"]).timestamp())
                except Exception:
                    continue
                applied += 1
        elif act == "add":
            if key not in ever and c["site"] in sites:
                d = parse_dir(c["type"])
                if d is None:
                    continue
                try:
                    ts = int(parse_iso(c["time"]).timestamp())
                except Exception:
                    continue
                punches[key] = [c["employee"], d, ts]
                ever.add(key)
                applied += 1

    empset = set(employees)
    by_emp = {}
    for (site, pid), (emp, d, ts) in punches.items():
        if emp in empset:
            by_emp.setdefault(emp, []).append((ts, 0 if d == "OUT" else 1, site, pid, d))

    res = {e: dict(shifts=0, paid=0, ot=0, night=0, gross=Fraction(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)

    def in_period(wd):
        return pstart <= wd <= pend

    for emp, plist in by_emp.items():
        hzone = sites[home[emp]][0] if home.get(emp) in sites else UTC
        plist.sort()
        # 3. duplicates
        kept = []
        for p in plist:
            ts, _, site, pid, d = p
            if kept and kept[-1][4] == d and ts - kept[-1][0] <= 300:
                rts = round_instant(ts, sites[site][0])
                if in_period(local_date(rts, hzone)):
                    exc["duplicates_dropped"] += 1
                continue
            kept.append(p)
        # 4. round
        rk = [(round_instant(p[0], sites[p[2]][0]), p[2], p[4]) for p in kept]
        # 5. pair
        shifts = []
        pending = None

        def wd(ts):
            return local_date(ts, hzone)

        for rts, site, d in rk:
            if d == "IN":
                if pending is not None:
                    if in_period(wd(pending[0])):
                        exc["open_shifts"] += 1
                pending = (rts, site)
            else:
                if pending is not None and rts - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], rts, pending[1]))
                    pending = None
                else:
                    if pending is not None:
                        if in_period(wd(pending[0])):
                            exc["open_shifts"] += 1
                        pending = None
                    if in_period(wd(rts)):
                        exc["orphan_outs"] += 1
        if pending is not None and in_period(wd(pending[0])):
            exc["open_shifts"] += 1

        # 6-9
        items = []
        for tin, tout, site in shifts:
            w = wd(tin)
            if not in_period(w):
                continue
            worked = max(0, (tout - tin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(tin, tout, sites[site][0]), paid)
            items.append([tin, w, paid, night, 0])
        items.sort(key=lambda x: x[0])
        day_used = {}
        for it in items:
            used = day_used.get(it[1], 0)
            reg = max(0, min(it[2], 480 - used))
            it.append(it[2] - reg)  # daily ot -> index 5
            day_used[it[1]] = used + it[2]
        week_used = {}
        for it in items:
            monday = it[1] - timedelta(days=it[1].weekday())
            nondaily = it[2] - it[5]
            used = week_used.get(monday, 0)
            wot = max(0, used + nondaily - max(2400, used)) if used + nondaily > 2400 else 0
            wot = min(wot, nondaily)
            week_used[monday] = used + nondaily
            ot = it[5] + wot
            reg = it[2] - ot
            rl = [r for r in rates.get(emp, []) if r[0] <= it[1]]
            rate = rl[-1][1] if rl else Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * it[3] / 60
            r = res[emp]
            r["shifts"] += 1
            r["paid"] += it[2]
            r["ot"] += ot
            r["night"] += it[3]
            r["gross"] += pay

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tgross = 0
    for e in sorted(employees):
        r = res[e]
        cents = round_half_up_cents(r["gross"])
        out_emps[e] = {
            "shifts": r["shifts"], "paid_minutes": r["paid"], "overtime_minutes": r["ot"],
            "night_minutes": r["night"], "gross": "%d.%02d" % divmod(cents, 100),
        }
        tot["shifts"] += r["shifts"]
        tot["paid_minutes"] += r["paid"]
        tot["overtime_minutes"] += r["ot"]
        tot["night_minutes"] += r["night"]
        tgross += cents
    tot["gross"] = "%d.%02d" % divmod(tgross, 100)
    exc["corrections_applied"] = applied
    out = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": out_emps,
        "exceptions": exc,
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outp))
    os.makedirs(d, exist_ok=True)
    with open(outp, "w") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
